(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c6-advanced-3"]={"id":"unit22-trap-c6-advanced-3","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"선지 변형 유형 · 주체","name":"심화 5지선다 3","level":"심화","desc":"2-2단원 · 주체","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"주체","parts":[{"name":"U22-33 · 야구장 경험을 든 목적","items":[{"paragraphCount":1,"readingLabel":"13문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 13문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 13문단]\n예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다. 그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다. 이렇듯 비싼 관람석에 앉을 수 있는 경제적 능력은 경기를 향한 열정보다는 주머니 사정과 관계가 깊을 수 있다. 오히려 경제적 여유는 없지만 선발 출전 선수들의 평균 타율을 전부 꿰고 있는 팬들, 특히 젊은 팬들이 그들보다 야구를 좋아하는 것만은 확실하다. 시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다. 어떨 때는 공연을 관람하거나 야구 경기를 보기 위해 자발적으로 줄을 서고자 하는 태도가 가격을 지불하고자 하는 태도보다 관람을 정말 원하는 사람을 나타내는 지표일 수 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["주체"],"id":"U22-33-S1","type":"mc","sent":"13문단의 내용과 맞는 설명은?","options":["글쓴이가 자신의 경험으로 든 것은 축구장에서 본 일이다.","글쓴이는 비싼 표를 사는 데 가진 돈은 중요하지 않고 야구를 좋아하는 마음만 중요하다고 본다.","글쓴이는 야구장에서 비싼 자리에 늦게 왔다가 일찍 가는 관객을 보았다. 비싼 표를 살 수 있다고 야구를 더 좋아하는 것은 아니라는 예다.","야구장의 사례는 비싼 표를 살수록 야구를 더 좋아한다고 판단할 수 있음을 보여 준다.","비싼 표를 살 수 있는지는 가진 돈과 언제나 상관없다고 본다."],"answer":"글쓴이는 야구장에서 비싼 자리에 늦게 왔다가 일찍 가는 관객을 보았다. 비싼 표를 살 수 있다고 야구를 더 좋아하는 것은 아니라는 예다.","why":"비싼 표를 사려면 돈이 있어야 해요. 하지만 비싼 자리를 산 관객도 경기를 끝까지 보지 않을 수 있으니, 표값만으로 야구를 얼마나 좋아하는지 알기는 어려워요.\n13문단에서 확인할 수 있어요.","choiceReviews":{"글쓴이는 야구장에서 비싼 자리에 늦게 왔다가 일찍 가는 관객을 보았다. 비싼 표를 살 수 있다고 야구를 더 좋아하는 것은 아니라는 예다.":{"reason":"비싼 표를 사려면 돈이 있어야 해요. 하지만 비싼 자리를 산 관객도 경기를 끝까지 보지 않을 수 있으니, 표값만으로 야구를 얼마나 좋아하는지 알기는 어려워요.\n13문단에서 확인할 수 있어요.","edits":[]},"글쓴이가 자신의 경험으로 든 것은 축구장에서 본 일이다.":{"reason":"바르게 고치면: 글쓴이가 자신의 경험으로 든 것은 야구장에서 본 일이다.\n비싼 표를 사려면 돈이 있어야 해요. 하지만 비싼 자리를 산 관객도 경기를 끝까지 보지 않을 수 있으니, 표값만으로 야구를 얼마나 좋아하는지 알기는 어려워요.\n13문단에서 확인할 수 있어요.","edits":[{"start":19,"end":25,"before":"축구장에서 ","after":"야구장에서 "}]},"글쓴이는 비싼 표를 사는 데 가진 돈은 중요하지 않고 야구를 좋아하는 마음만 중요하다고 본다.":{"reason":"바르게 고치면: 글쓴이는 비싼 표를 사는 데 야구를 좋아하는 마음보다 가진 돈이 더 중요할 수 있다고 본다.\n비싼 표를 사려면 돈이 있어야 해요. 하지만 비싼 자리를 산 관객도 경기를 끝까지 보지 않을 수 있으니, 표값만으로 야구를 얼마나 좋아하는지 알기는 어려워요.\n13문단에서 확인할 수 있어요.","edits":[{"start":16,"end":30,"before":"가진 돈은 중요하지 않고 ","after":""},{"start":39,"end":49,"before":"마음만 중요하다고 ","after":"마음보다 가진 돈이 더 중요할 수 있다고 "}]},"야구장의 사례는 비싼 표를 살수록 야구를 더 좋아한다고 판단할 수 있음을 보여 준다.":{"reason":"바르게 고치면: 야구장의 사례는 비싼 표를 살수록 야구를 더 좋아한다고 판단할 수 없음을 보여 준다.\n비싼 표를 사려면 돈이 있어야 해요. 하지만 비싼 자리를 산 관객도 경기를 끝까지 보지 않을 수 있으니, 표값만으로 야구를 얼마나 좋아하는지 알기는 어려워요.\n13문단에서 확인할 수 있어요.","edits":[{"start":37,"end":41,"before":"있음을 ","after":"없음을 "}]},"비싼 표를 살 수 있는지는 가진 돈과 언제나 상관없다고 본다.":{"reason":"바르게 고치면: 비싼 표를 살 수 있는지는 가진 돈에 달려 있을 수 있다고 본다.\n비싼 표를 사려면 돈이 있어야 해요. 하지만 비싼 자리를 산 관객도 경기를 끝까지 보지 않을 수 있으니, 표값만으로 야구를 얼마나 좋아하는지 알기는 어려워요.\n13문단에서 확인할 수 있어요.","edits":[{"start":18,"end":31,"before":"돈과 언제나 상관없다고 ","after":"돈에 달려 있을 수 있다고 "}]}},"pageSpecificReasons":true,"evidence":{"title":"야구장 경험을 든 목적","statement":"글쓴이는 야구장에서 비싼 자리에 늦게 왔다가 일찍 가는 관객을 보았다. 비싼 표를 살 수 있다고 야구를 더 좋아하는 것은 아니라는 예다.","explanation":"비싼 표를 사려면 돈이 있어야 해요. 하지만 비싼 자리를 산 관객도 경기를 끝까지 보지 않을 수 있으니, 표값만으로 야구를 얼마나 좋아하는지 알기는 어려워요.\n13문단에서 확인할 수 있어요.","valid":["L13:1","L13:2","L13:3","L13:5"],"sources":[{"id":"L13","title":"줄 서기를 돈으로 살 수 있을까","label":"13문단","sentences":[{"id":"L13:1","text":"예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다.","paragraph":0,"memberIds":["L13:1"],"topic":"예를 들어 필자는 야구장에서 이런 사람들을 자주 본다. 늦게 와서 비싼 자리에 앉았다가 일찍 가 버리는 사람들이다."},{"id":"L13:2","text":"그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다.","paragraph":0,"memberIds":["L13:2"],"topic":"그럴 때 필자는 '저 사람들, 야구를 정말 좋아하는 걸까?' 하고 의심한다."},{"id":"L13:3","text":"이렇듯 비싼 관람석에 앉을 수 있는 경제적 능력은 경기를 향한 열정보다는 주머니 사정과 관계가 깊을 수 있다.","paragraph":0,"memberIds":["L13:3"],"topic":"이처럼 비싼 자리에 앉는 건 경기를 좋아하는 마음 때문이라기보다 돈이 많아서일 수 있다."},{"id":"L13:4","text":"오히려 경제적 여유는 없지만 선발 출전 선수들의 평균 타율을 전부 꿰고 있는 팬들, 특히 젊은 팬들이 그들보다 야구를 좋아하는 것만은 확실하다.","paragraph":0,"memberIds":["L13:4"],"topic":"오히려 돈은 없어도 선발 선수들의 타율(안타를 치는 비율)을 다 외우는 팬, 특히 젊은 팬들이 그 사람들보다 야구를 더 좋아하는 건 확실하다."},{"id":"L13:5","text":"시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다.","paragraph":0,"memberIds":["L13:5"],"topic":"가격에는 마음과 돈(능력)이 같이 들어 있다. 그래서 가격만 보고는 누가 가장 좋아하는지 정확히 알 수 없다. 가격은 정확하지 않은 자(불완전한 지표)다."},{"id":"L13:6","text":"어떨 때는 공연을 관람하거나 야구 경기를 보기 위해 자발적으로 줄을 서고자 하는 태도가 가격을 지불하고자 하는 태도보다 관람을 정말 원하는 사람을 나타내는 지표일 수 있다.","paragraph":0,"memberIds":["L13:6"],"topic":"때로는 '몇 시간이라도 줄 서겠다'는 마음이 '돈을 내겠다'는 마음보다 진짜 팬을 더 잘 보여 줄 수 있다."}]}]},"editorSourceVersion":"5beff96bc65d185185bf35ad538cee55623883fbf683ace3ab3b17c60d111c38"}]}]};})(window);
